'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var FLOAT32_MAX = require( '@stdlib/constants/float32/max' );
var SMALLEST_SUBNORMAL = require( '@stdlib/constants/float32/smallest-subnormal' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var trunc10f = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( trunc10f instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof trunc10f, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `+0` if provided `+0`', opts, function test( t ) {
	var v;

	v = trunc10f( 0.0 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );

	v = trunc10f( +0.0 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-0` if provided `-0`', opts, function test( t ) {
	var v = trunc10f( -0.0 );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` if provided a `NaN`', opts, function test( t ) {
	var v = trunc10f( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', opts, function test( t ) {
	var v = trunc10f( PINF );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', opts, function test( t ) {
	var v = trunc10f( NINF );
	t.strictEqual( v, NINF, 'returns expected value' );
	t.end();
});

tape( 'the function does not overflow', opts, function test( t ) {
	var v;

	v = trunc10f( FLOAT32_MAX );
	t.strictEqual( v, f32( 1.0e38 ), 'returns expected value' );

	v = trunc10f( -FLOAT32_MAX );
	t.strictEqual( v, f32( -1.0e38 ), 'returns expected value' );

	t.end();
});

tape( 'the function supports rounding subnormal values', opts, function test( t ) {
	var v;

	v = trunc10f( 1.5e-44 );
	t.strictEqual( v, f32( 1.0e-44 ), 'returns expected value' );

	v = trunc10f( 8.5e-44 );
	t.strictEqual( v, f32( 1.0e-44 ), 'returns expected value' );

	v = trunc10f( -1.5e-44 );
	t.strictEqual( v, f32( -1.0e-44 ), 'returns expected value' );

	v = trunc10f( -8.5e-44 );
	t.strictEqual( v, f32( -1.0e-44 ), 'returns expected value' );

	v = trunc10f( SMALLEST_SUBNORMAL );
	t.strictEqual( v, f32( 1.0e-45 ), 'returns expected value' );

	v = trunc10f( -SMALLEST_SUBNORMAL );
	t.strictEqual( v, f32( -1.0e-45 ), 'returns expected value' );

	t.end();
});

tape( 'the function rounds a single-precision floating-point number to the nearest power of 10 toward zero', opts, function test( t ) {
	t.strictEqual( trunc10f( -4.2 ), -1.0, 'returns expected value' );
	t.strictEqual( trunc10f( -4.5 ), -1.0, 'returns expected value' );
	t.strictEqual( trunc10f( -4.8 ), -1.0, 'returns expected value' );
	t.strictEqual( trunc10f( 4.2 ), 1.0, 'returns expected value' );
	t.strictEqual( trunc10f( 9.99999 ), 1.0, 'returns expected value' );
	t.strictEqual( trunc10f( 9.5 ), 1.0, 'returns expected value' );
	t.strictEqual( trunc10f( 9.4 ), 1.0, 'returns expected value' );
	t.strictEqual( trunc10f( 12.0 ), 10.0, 'returns expected value' );
	t.strictEqual( trunc10f( -12.0 ), -10.0, 'returns expected value' );
	t.strictEqual( trunc10f( 13.0 ), 10.0, 'returns expected value' );
	t.strictEqual( trunc10f( -13.0 ), -10.0, 'returns expected value' );
	t.strictEqual( trunc10f( 23.0 ), 10.0, 'returns expected value' );
	t.strictEqual( trunc10f( -23.0 ), -10.0, 'returns expected value' );
	t.strictEqual( trunc10f( 27.0 ), 10.0, 'returns expected value' );
	t.strictEqual( trunc10f( -27.0 ), -10.0, 'returns expected value' );
	t.strictEqual( trunc10f( 48.1 ), 10.0, 'returns expected value' );
	t.strictEqual( trunc10f( -48.1 ), -10.0, 'returns expected value' );
	t.strictEqual( trunc10f( 0.3 ), f32( 0.1 ), 'returns expected value' );
	t.strictEqual( trunc10f( -0.3 ), f32( -0.1 ), 'returns expected value' );
	t.strictEqual( trunc10f( 0.45 ), f32( 0.1 ), 'returns expected value' );
	t.strictEqual( trunc10f( -0.45 ), f32( -0.1 ), 'returns expected value' );
	t.end();
});

tape( 'the function returns correctly rounded powers of ten', opts, function test( t ) {
	// The following expected values are powers of ten for which `powf` does not return the closest single-precision floating-point number to the corresponding exact power of ten...
	t.strictEqual( trunc10f( 2.0e-36 ), f32( 1.0e-36 ), 'returns expected value' );
	t.strictEqual( trunc10f( -2.0e-36 ), f32( -1.0e-36 ), 'returns expected value' );
	t.strictEqual( trunc10f( 2.0e-22 ), f32( 1.0e-22 ), 'returns expected value' );
	t.strictEqual( trunc10f( -2.0e-22 ), f32( -1.0e-22 ), 'returns expected value' );
	t.strictEqual( trunc10f( 2.0e-18 ), f32( 1.0e-18 ), 'returns expected value' );
	t.strictEqual( trunc10f( -2.0e-18 ), f32( -1.0e-18 ), 'returns expected value' );
	t.strictEqual( trunc10f( 2.0e11 ), f32( 1.0e11 ), 'returns expected value' );
	t.strictEqual( trunc10f( -2.0e11 ), f32( -1.0e11 ), 'returns expected value' );
	t.end();
});
